style.css:
@-moz-document domain("google.com") {
html, body {
    background-color: rgb(255, 185, 208) !important;
    background-image: url("data:image/png;base64,") !important;
    background-repeat: repeat !important;
    background-size: 280px 204px !important;
    background-position: center top !important;
  }
 
  /* kill every solid-color wrapper Google stacks on top of body,
     including the dark top search bar and the white strip above results */
  #rcnt, #center_col, #search, #rso, #cnt, #main, #appbar,
  .sfbg, .minidiv, #searchform, .RNNXgb, .A8SBwf, .M8OgIe,
  .crJ18e, .Ww4FFb, .logo, #hdtb, #hdtbSum, .lncib, .O1uJvd {
    background: transparent !important;
    background-color: transparent !important;
  }
 
  /* light readability boxes only behind individual result blocks */
  .g, .MjjYud {
    background-color: rgba(255, 255, 255, 0.75) !important;
    border-radius: 8px;
    padding: 8px;
    border: none !important;
    box-shadow: none !important;
  }
 
  /* kill the stray divider lines that show up once backgrounds go transparent */
  #rcnt, #center_col, #search, #rso, #cnt, #main, #appbar,
  .sfbg, .minidiv, #searchform, .RNNXgb, .A8SBwf, .M8OgIe,
  .crJ18e, .Ww4FFb, .logo, #hdtb, #hdtbSum, .lncib, .O1uJvd,
  .MUFPAc, .hdtb-mitem, .g-blk, .kp-hc, .kp-blk, hr {
    border: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
  }
}
